FUNCTION_BLOCK FB
VAR_INPUT
    enqueue  : BOOL;
    dequeue  : BOOL;
    reset    : BOOL;
    capacity : DINT;
END_VAR
VAR_OUTPUT
    elementCount : DINT := 0;
    status       : WORD := 16#0000;
END_VAR
VAR_IN_OUT
    item   : DINT;
    buffer : ARRAY[1..4] OF DINT;
END_VAR
VAR
    head          : DINT := 1;
    tail          : DINT := 1;
    enqueue_prev  : BOOL := FALSE;
    dequeue_prev  : BOOL := FALSE;
    storedCapacity: DINT := 4;
    initialized   : BOOL := FALSE;
END_VAR

IF NOT initialized THEN
    storedCapacity := capacity;
    initialized := TRUE;
END_IF;

IF reset THEN
    head := 1;
    tail := 1;
    elementCount := 0;
    status := 16#0000;
    enqueue_prev := FALSE;
    dequeue_prev := FALSE;
    RETURN;
END_IF;

enqueue_edge := enqueue AND NOT enqueue_prev;
dequeue_edge := dequeue AND NOT dequeue_prev;

enqueue_prev := enqueue;
dequeue_prev := dequeue;

IF enqueue_edge THEN
    IF elementCount < storedCapacity THEN
        buffer[tail] := item;
        tail := ((tail - 1) MOD storedCapacity) + 1;
        elementCount := elementCount + 1;
        status := 16#0000;
    ELSE
        status := 16#8002;
    END_IF;
END_IF;

IF dequeue_edge THEN
    IF elementCount > 0 THEN
        item := buffer[head];
        head := ((head - 1) MOD storedCapacity) + 1;
        elementCount := elementCount - 1;
        IF elementCount = 0 THEN
            head := 1;
            tail := 1;
        END_IF;
        status := 16#0000;
    ELSE
        status := 16#8001;
    END_IF;
END_IF;

END_FUNCTION_BLOCK
